using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.EditorInput;
using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class EntityScaleTestsV1 {
 public class Config {public string input,input_sha256,output,receipt;public string[] handles;public double before,after;}
 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000};
 static void Need(bool b,string m){if(!b)throw new InvalidOperationException(m);}
 [CommandMethod("HLCADENTITYSCALETESTV1",CommandFlags.Session)]public void Run(){var a=App.DocumentManager.MdiActiveDocument.Editor.GetString(new PromptStringOptions("\nEntity scale test: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;Config c=null;var previous=HostApplicationServices.WorkingDatabase;
 try{c=J.Deserialize<Config>(File.ReadAllText(a.StringResult.Trim('"')));Need(BoundCadEditsV6.Hash(c.input)==c.input_sha256&&!File.Exists(c.output)&&!File.Exists(c.receipt),"EXACT_TEST_FILES_REQUIRED");BoundCadEditsV6.Job job;string expected;object changes;var touched=new HashSet<string>();
 using(var db=new Database(false,true)){db.ReadDwgFile(c.input,FileOpenMode.OpenForReadAndAllShare,true,null);db.CloseInput(true);HostApplicationServices.WorkingDatabase=db;
 using(var tr=db.TransactionManager.StartTransaction()){var edits=new List<BoundCadEditsV6.DisplayEdit>();foreach(string h in c.handles){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(h,16)),0),OpenMode.ForRead);Need(e.OwnerId==SymbolUtilityServices.GetBlockModelSpaceId(db)&&e.LinetypeScale==c.before,"CURRENT_TARGET_SCALE_OR_OWNER_CHANGED");edits.Add(new BoundCadEditsV6.DisplayEdit{target=BoundCadEditsV6.Identity(e),before_color=(short)e.ColorIndex,color=(short)e.ColorIndex,target_layer=e.Layer,before_linetype_scale=c.before,linetype_scale=c.after});}job=new BoundCadEditsV6.Job{entities=edits.ToArray()};}
 var before=PresentationVerifyV1.Snapshot(db,job,"entity_display");var invalid=J.Deserialize<BoundCadEditsV6.Job>(J.Serialize(job));invalid.entities[0].before_linetype_scale=c.before+1;bool rejected=false;try{EntityDisplayOpsV1.Apply(db,invalid);}catch(InvalidOperationException){rejected=true;}Need(rejected&&before==PresentationVerifyV1.Snapshot(db,job,"entity_display"),"STALE_VALUE_NOT_REJECTED_WITHOUT_CHANGE");
 var defaultJob=J.Deserialize<BoundCadEditsV6.Job>(J.Serialize(job));foreach(var e in defaultJob.entities){e.before_linetype_scale=null;e.linetype_scale=null;}EntityDisplayOpsV1.Apply(db,defaultJob);Need(before==PresentationVerifyV1.Snapshot(db,job,"entity_display"),"OMITTED_SCALE_CHANGED_VALUE");
 ObjectEventHandler modified=(s,e)=>{if(e.DBObject is Entity&&!c.handles.Contains(e.DBObject.Handle.ToString(),StringComparer.OrdinalIgnoreCase))touched.Add(e.DBObject.Handle.ToString());};db.ObjectModified+=modified;db.ObjectAppended+=modified;try{changes=EntityDisplayOpsV1.Apply(db,job);Need(touched.Count==0,"UNSELECTED_ENTITY_CHANGED");}finally{db.ObjectModified-=modified;db.ObjectAppended-=modified;}
 expected=PresentationVerifyV1.Snapshot(db,job,"entity_display");db.SaveAs(c.output,DwgVersion.AC1032);HostApplicationServices.WorkingDatabase=previous;}
 using(var db=new Database(false,true)){db.ReadDwgFile(c.output,FileOpenMode.OpenForReadAndAllShare,true,null);db.CloseInput(true);HostApplicationServices.WorkingDatabase=db;Need(CadValueCompareV1.Json(expected,PresentationVerifyV1.Snapshot(db,job,"entity_display")),"SAVED_SCALE_REOPEN_CHANGED");HostApplicationServices.WorkingDatabase=previous;}
 Need(BoundCadEditsV6.Hash(c.input)==c.input_sha256,"SOURCE_CHANGED");File.WriteAllText(c.receipt,J.Serialize(new{status="ISOLATED_ENTITY_SCALE_SAVE_REOPEN_VERIFIED",changes=changes,parameters=new{entities=job.entities},stale_before_rejected=true,omitted_scale_preserved=true,unselected_entities_unchanged=true,source_unchanged=true,output=c.output,sha256=BoundCadEditsV6.Hash(c.output)}));
 }catch(System.Exception e){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="ENTITY_SCALE_TEST_FAILED",error=e.ToString()}));}finally{HostApplicationServices.WorkingDatabase=previous;}
 }
}
